main.script:
(function () {
  'use strict';
  function $(s, c) { return (c || document).querySelector(s); }
  function $all(s, c) { return Array.prototype.slice.call((c || document).querySelectorAll(s)); }
  function clamp(v, a, b) { return v < a ? a : v > b ? b : v; }
  var HEAD = 70, NS = 'http://www.w3.org/2000/svg';
  function svgEl(tag, attrs) { var e = document.createElementNS(NS, tag); for (var k in attrs) e.setAttribute(k, attrs[k]); return e; }
  /* one rAF-throttled handler for scroll + resize */
  function onScroll(fn) {
    var t = false; function run() { t = false; fn(); }
    function q() { if (!t) { t = true; requestAnimationFrame(run); } }
    window.addEventListener('scroll', q, { passive: true }); window.addEventListener('resize', q, { passive: true });
  }

  /* =========================================================
     1 · HOW IT WORKS — three stages on one drawn line. The live field
     (TRELayer.tremor, one canvas per stage, cross-faded) goes from a tight,
     charged bundle (activation) to shivering (tremor) to slow open waves
     (regulation). Scrolling steps through it; the step buttons, the nodes
     and the arrow keys choose a stage directly. Illustrative, no data.
     ========================================================= */
  var FIELD = [
    { lines: 9, top: .41, bottom: .59, amp: 4, wave: [110, 190], breath: 2.6, shiver: 2.4, reach: 520, settle: 2.3, alpha: [.34, .88], width: 1.25, fade: .1, idlePulse: 0, colors: ['224,180,100', '243,232,210', '201,164,92'] },
    { lines: 9, top: .26, bottom: .74, amp: 9, wave: [200, 360], breath: 4.6, shiver: 8.5, reach: 240, settle: 1.5, alpha: [.28, .84], width: 1.25, fade: .1, idlePulse: 0, colors: ['201,164,92', '243,232,210', '205,216,234'] },
    { lines: 9, top: .15, bottom: .85, amp: 15, wave: [480, 860], breath: 8, shiver: 6, reach: 150, settle: 2.3, alpha: [.2, .66], width: 1.2, fade: .1, idlePulse: 0, colors: ['205,216,234', '243,232,210', '201,164,92'] }
  ];
  /* the drawn line: taut and humming (activation), shaking (tremor), long settling waves (regulation) */
  function offset(kind, s, len) {
    var u = len ? s / len : 0, tap = Math.max(0, Math.min(1, s / 12, (len - s) / 12)), T = Math.PI * 2;
    if (kind === 'charge') return tap * (.45 + 2.6 * u * u) * Math.sin(T * s / 6.5);
    if (kind === 'tremor') return tap * (1.4 + 6.2 * Math.sin(Math.PI * u)) * (.62 * Math.sin(T * s / 10.5) + .38 * Math.sin(T * s / 6.2 + 1.3));
    if (kind === 'calm') return tap * 5.5 * Math.pow(1 - u, 1.5) * Math.sin(T * s / 150);
    return 0;
  }
  function trace(a, b, base, kind, vertical) {
    var len = Math.max(0, b - a), st = (kind === 'charge' || kind === 'tremor') ? 1.2 : 3, n = Math.max(1, Math.ceil(len / st)), d = '';
    for (var i = 0; i <= n; i++) {
      var s = len * i / n, q = base + offset(kind, s, len), p = a + s;
      d += (i ? 'L' : 'M') + (vertical ? q.toFixed(1) + ' ' + p.toFixed(1) : p.toFixed(1) + ' ' + q.toFixed(1));
    }
    return d;
  }
  function initStage(L, R) {
    var stage = $('[data-ed-stage]'); if (!stage) return;
    var view = $('.ed-stage-view', stage), wrap = $('.ed-flow-wrap', stage), svg = $('.ed-flow', stage);
    var steps = $all('.ed-step', stage), cvs = $all('.ed-cv', stage);
    if (!wrap || !svg || steps.length !== 3) return;
    stage.classList.add('is-live');

    /* the step headings become buttons (Tab, Enter/Space, arrow keys, Home/End) */
    var btns = steps.map(function (s) {
      var lbl = $('.ed-step-lbl', s), b = document.createElement('button');
      b.type = 'button'; b.className = 'ed-step-btn';
      if (lbl) { while (lbl.firstChild) b.appendChild(lbl.firstChild); lbl.parentNode.replaceChild(b, lbl); }
      return b;
    });

    var inst = [], dummy = document.createElement('div');   /* pointer input is forwarded by this script */
    if (L && L.tremor && view && cvs.length === 3) {
      cvs.forEach(function (c, i) { var o = { source: dummy }; for (var k in FIELD[i]) o[k] = FIELD[i][k]; inst[i] = L.tremor(c, o); });
      cvs[0].classList.add('is-on');
    } else if (view) view.classList.add('is-off');

    var cur = 0, visible = false, raf = 0, ptr = null, lastPulse = 0, stopT = 0, manual = false, manualY = 0, segs = [], nodes = [];

    function sleepOthers() { inst.forEach(function (I, i) { if (I && i !== cur) I.stop(); }); }
    function kick() { if (!raf && visible && !R && inst.length) raf = requestAnimationFrame(drive); }
    /* a slow virtual hand keeps the activation bundle humming and sends waves of tremor through stage 2 */
    function drive(now) {
      raf = 0; if (!visible || document.hidden) return;
      var I = inst[cur]; if (!I) return;
      var w = view.clientWidth, h = view.clientHeight, t = now / 1000;
      var held = !!(L.motion && L.motion.paused);   /* the site's pause switch stops the virtual hand; the visitor's own pointer still plays */
      if (ptr) I.poke(ptr.x, ptr.y);
      else if (held) { /* still */ }
      else if (cur === 0) I.poke(w * (.5 + .24 * Math.sin(t * .31)), h * .5);
      else if (cur === 1) {
        I.poke(w * (.5 + .42 * Math.sin(t * .47)), h * (.5 + .14 * Math.sin(t * .83)));
        if (now - lastPulse > 1900) { lastPulse = now; I.pulse(-60, Math.floor(Math.random() * 9)); }
      }
      if (ptr || (cur !== 2 && !held)) raf = requestAnimationFrame(drive);
    }
    if (L && L.motion) L.motion.on(function (p) { if (!p) kick(); });
    function paint(prev) {
      var n = cur, first = prev == null;
      segs.forEach(function (p, i) {
        var on = i <= n + 1, delay = 0;
        if (!first && !R) {
          if (n > prev && on && i > prev + 1) delay = (i - prev - 2) * .5;
          else if (n < prev && !on && i <= prev + 1) delay = (prev + 1 - i) * .3;
        }
        p.style.transition = first ? 'none' : '';
        p.style.transitionDelay = delay ? delay + 's' : '';
        p.classList.toggle('on', on);
      });
      if (first && segs.length) { void svg.getBoundingClientRect(); segs.forEach(function (p) { p.style.transition = ''; }); }
      nodes.forEach(function (g, i) { g.classList.toggle('on', i === n); g.classList.toggle('past', i < n); });
      steps.forEach(function (s, i) { s.classList.toggle('is-on', i === n); s.classList.toggle('is-past', i < n); });
      btns.forEach(function (b, i) { if (i === n) b.setAttribute('aria-current', 'step'); else b.removeAttribute('aria-current'); });
    }
    function setState(n) {
      if (n === cur) return;
      var prev = cur; cur = n;
      if (inst.length) cvs.forEach(function (c, i) {
        c.classList.remove('from-lo', 'from-hi', 'to-lo', 'to-hi');
        if (i === n) {
          if (!R) { c.classList.add(n > prev ? 'from-lo' : 'from-hi'); void c.offsetWidth; c.classList.remove('from-lo', 'from-hi'); }
          c.classList.add('is-on');
        } else {
          if (i === prev && !R) c.classList.add(n > prev ? 'to-hi' : 'to-lo');
          c.classList.remove('is-on');
        }
      });
      if (inst[n]) { inst[n].start(); if (inst[prev]) inst[prev].poke(-1e4, -1e4); }
      clearTimeout(stopT); stopT = setTimeout(sleepOthers, 1600);
      paint(prev); kick();
    }
    function choose(i) { manual = true; manualY = window.pageYOffset; setState(i); }
    function build() {
      var vertical = window.matchMedia('(max-width: 899px)').matches;
      var box = svg.getBoundingClientRect(), W = box.width, H = box.height;
      if (W < 2 || H < 2) return;
      svg.setAttribute('viewBox', '0 0 ' + W.toFixed(1) + ' ' + H.toFixed(1));
      var pos = steps.map(function (s, i) {
        if (vertical) { var r = btns[i].getBoundingClientRect(); return r.top + r.height / 2 - box.top; }
        return s.getBoundingClientRect().left - box.left + 10;
      });
      var base = vertical ? 15 : H / 2, marks = [0, pos[0], pos[1], pos[2], vertical ? H : W], kinds = ['lead', 'charge', 'tremor', 'calm'];
      while (svg.firstChild) svg.removeChild(svg.firstChild);
      var gT = svgEl('g', {}), gP = svgEl('g', {}), gN = svgEl('g', {});
      segs = kinds.map(function (k, i) {
        var d = trace(marks[i], marks[i + 1], base, k, vertical);
        gT.appendChild(svgEl('path', { 'class': 'tk', d: d }));
        var p = svgEl('path', { 'class': 'pg', d: d, pathLength: '1' }); gP.appendChild(p); return p;
      });
      nodes = pos.map(function (v, i) {
        var g = svgEl('g', { 'class': 'nd', transform: 'translate(' + (vertical ? base : v).toFixed(1) + ' ' + (vertical ? v : base).toFixed(1) + ')' });
        g.appendChild(svgEl('circle', { 'class': 'halo', r: '15' }));
        g.appendChild(svgEl('circle', { 'class': 'dot', r: '7.5' }));
        g.addEventListener('click', function () { choose(i); });
        gN.appendChild(g); return g;
      });
      svg.appendChild(gT); svg.appendChild(gP); svg.appendChild(gN);
      paint(null);
    }
    /* scroll position -> stage: centred stages step through as they rise; tall (phone) stages follow the reading line */
    function map() {
      var vh = window.innerHeight, y = window.pageYOffset;
      if (manual) { if (Math.abs(y - manualY) < vh * .6) return; manual = false; }
      var r = stage.getBoundingClientRect(); if (r.bottom < 0 || r.top > vh) return;
      var n = 0;
      if (r.height <= vh - HEAD - 24) {
        var p = (vh * .75 - (r.top + r.bottom) / 2) / (vh * .45);
        n = p < .34 ? 0 : p < .67 ? 1 : 2;
      } else {
        var line = vh * .7;
        steps.forEach(function (s, i) { if (s.getBoundingClientRect().top < line) n = i; });
      }
      setState(n);
    }

    btns.forEach(function (b, i) {
      b.addEventListener('click', function () { choose(i); });
      b.addEventListener('keydown', function (e) {
        var j = null;
        if (e.key === 'ArrowRight' || e.key === 'ArrowDown') j = Math.min(2, i + 1);
        else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') j = Math.max(0, i - 1);
        else if (e.key === 'Home') j = 0; else if (e.key === 'End') j = 2;
        if (j === null) return;
        e.preventDefault(); btns[j].focus(); choose(j);
      });
    });
    steps.forEach(function (s, i) { s.addEventListener('click', function (e) { if (!e.target.closest('button, a')) choose(i); }); });
    if (view && inst.length) {
      view.addEventListener('pointermove', function (e) { var r = view.getBoundingClientRect(); ptr = { x: e.clientX - r.left, y: e.clientY - r.top }; kick(); }, { passive: true });
      view.addEventListener('pointerleave', function () { ptr = null; if (inst[cur]) inst[cur].poke(-1e4, -1e4); kick(); });
    }
    if (L && L.onVisible) L.onVisible(stage, function (en, isIn) { visible = isIn; if (isIn) { kick(); setTimeout(sleepOthers, 300); } });
    else visible = true;

    build();
    if ('ResizeObserver' in window) { var rq = 0; new ResizeObserver(function () { cancelAnimationFrame(rq); rq = requestAnimationFrame(build); }).observe(wrap); }
    else window.addEventListener('resize', build);
    onScroll(map); map();
  }

  /* =========================================================
     2 · CHECKLISTS — each tick draws in as the list comes into view
     ========================================================= */
  function initTicks(L, R) {
    $all('[data-ed-ticks]').forEach(function (ul) {
      $all('li', ul).forEach(function (li, i) { li.style.setProperty('--i', i); });
      if (R || !L || !L.onVisible) return;
      ul.classList.add('ed-notr', 'ed-pre'); void ul.offsetWidth; ul.classList.remove('ed-notr');
      L.onVisible(ul, function (en, isIn) { if (isIn) ul.classList.add('is-in'); }, { once: true, threshold: .3 });
    });
  }

  /* =========================================================
     3 · AUDIENCES — four blocks become a segmented selector (ARIA tabs)
     ========================================================= */
  function initTabs() {
    var box = $('[data-ed-tabs]'); if (!box) return;
    var panels = $all('.ed-aud-panel', box); if (panels.length < 2) return;
    var list = document.createElement('div'), ind = document.createElement('span');
    list.className = 'ed-aud-tabs no-tr'; list.setAttribute('role', 'tablist'); list.setAttribute('aria-labelledby', 'ed-aud-h');
    ind.className = 'ed-aud-ind'; ind.setAttribute('aria-hidden', 'true'); list.appendChild(ind);
    var tabs = panels.map(function (p, i) {
      var tag = $('.ed-aud-tag', p), b = document.createElement('button');
      b.type = 'button'; b.className = 'ed-aud-tab'; b.id = 'ed-aud-t' + (i + 1);
      b.setAttribute('role', 'tab'); b.setAttribute('aria-controls', p.id);
      b.textContent = (tag || $('h3', p)).textContent;
      p.setAttribute('role', 'tabpanel'); p.setAttribute('aria-labelledby', b.id); p.setAttribute('tabindex', '0');
      list.appendChild(b); return b;
    });
    box.insertBefore(list, box.firstChild); box.classList.add('is-tabs');
    var cur = -1;
    function place() { var b = tabs[cur]; if (!b) return; ind.style.width = b.offsetWidth + 'px'; ind.style.height = b.offsetHeight + 'px'; ind.style.transform = 'translate(' + b.offsetLeft + 'px,' + b.offsetTop + 'px)'; }
    function select(i, focus) {
      if (i === cur) return; cur = i;
      tabs.forEach(function (b, j) { var on = j === i; b.setAttribute('aria-selected', on ? 'true' : 'false'); b.tabIndex = on ? 0 : -1; panels[j].classList.toggle('is-on', on); });
      if (focus) tabs[i].focus();
      place();
    }
    tabs.forEach(function (b, i) { b.addEventListener('click', function () { select(i); }); });
    list.addEventListener('keydown', function (e) {
      var n = tabs.length, j = null;
      if (e.key === 'ArrowRight' || e.key === 'ArrowDown') j = (cur + 1) % n;
      else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') j = (cur - 1 + n) % n;
      else if (e.key === 'Home') j = 0; else if (e.key === 'End') j = n - 1;
      if (j === null) return;
      e.preventDefault(); select(j, true);
    });
    select(0);
    requestAnimationFrame(function () { place(); requestAnimationFrame(function () { list.classList.remove('no-tr'); }); });
    if ('ResizeObserver' in window) new ResizeObserver(place).observe(list); else window.addEventListener('resize', place);
    if (document.fonts && document.fonts.ready) document.fonts.ready.then(place);
  }

  /* =========================================================
     4 · CERTIFICATION — the path lights up to each module as you read down
     (and stays lit); nodes fill when the reading line reaches them
     ========================================================= */
  function initPath(R) {
    var path = $('[data-ed-path]'); if (!path || R) return;
    var mods = $all('.ed-mod', path), nodes = mods.map(function (m) { return $('.ed-node', m); });
    if (!mods.length || nodes.some(function (n) { return !n; })) return;
    var fill = mods.map(function () { return 0; });
    path.classList.add('is-live');
    function update() {
      var line = window.innerHeight * .62, c = nodes.map(function (n) { var r = n.getBoundingClientRect(); return r.top + r.height / 2; });
      mods.forEach(function (m, i) {
        if (c[i] < line) m.classList.add('is-on');
        if (i < mods.length - 1) {
          var f = Math.max(fill[i], clamp((line - c[i]) / Math.max(1, c[i + 1] - c[i]), 0, 1));
          if (f !== fill[i]) { fill[i] = f; m.style.setProperty('--fill', f.toFixed(3)); }
        }
      });
    }
    mods.forEach(function (m, i) { if (i < mods.length - 1) m.style.setProperty('--fill', '0'); });
    onScroll(update); update();
  }

  /* =========================================================
     5 · FEES — row + column highlight on hover and keyboard focus
     (one tab stop; the arrow keys move between the fee cells)
     ========================================================= */
  function initTable() {
    var t = $('.ed-table'); if (!t) return;
    var rows = $all('tbody tr', t), grid = rows.map(function (tr) { return $all('td', tr); });
    function mark(r, c) {
      if (c > 0) t.setAttribute('data-hc', String(c)); else t.removeAttribute('data-hc');
      rows.forEach(function (tr, i) { tr.classList.toggle('is-hr', i === r); });
      grid.forEach(function (cells, i) { cells.forEach(function (td) { td.classList.toggle('is-hc', i === r && td.cellIndex === c); }); });
    }
    t.addEventListener('pointerover', function (e) {
      var cell = e.target.closest('td, th'); if (!cell || !t.contains(cell)) return;
      mark(rows.indexOf(cell.parentElement), cell.cellIndex);
    });
    t.addEventListener('pointerleave', function () { if (!t.contains(document.activeElement)) mark(-1, 0); });
    grid.forEach(function (cells, r) {
      cells.forEach(function (td, c) {
        td.tabIndex = r === 0 && c === 0 ? 0 : -1;
        td.addEventListener('focus', function () { grid.forEach(function (cs) { cs.forEach(function (x) { x.tabIndex = -1; }); }); td.tabIndex = 0; mark(r, td.cellIndex); });
        td.addEventListener('keydown', function (e) {
          var r2 = r, c2 = c;
          if (e.key === 'ArrowRight') c2++; else if (e.key === 'ArrowLeft') c2--;
          else if (e.key === 'ArrowDown') r2++; else if (e.key === 'ArrowUp') r2--;
          else if (e.key === 'Home') c2 = 0; else if (e.key === 'End') c2 = cells.length - 1;
          else return;
          r2 = clamp(r2, 0, grid.length - 1); c2 = clamp(c2, 0, grid[r2].length - 1);
          e.preventDefault(); grid[r2][c2].focus();
        });
      });
    });
    t.addEventListener('focusout', function (e) { if (!e.relatedTarget || !t.contains(e.relatedTarget)) mark(-1, 0); });
  }

  /* =========================================================
     6 · CLOSE — the tremor field again, and one line forking into the two paths
     ========================================================= */
  function initClose(L, R) {
    var box = $('[data-ed-close]'); if (!box) return;
    var cv = $('.ed-close-cv', box);
    if (L && L.tremor && cv) L.tremor(cv, { source: box, lines: 6, top: .62, bottom: .97, alpha: [.07, .26], fade: .2 });
    if (R || !L || !L.onVisible) return;
    box.classList.add('ed-pre');
    L.onVisible(box, function (en, isIn) { if (isIn) box.classList.add('is-in'); }, { once: true, threshold: .35 });
  }

  function init() {
    var L = window.TRELayer || null;
    var R = L ? !!L.reduced : !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
    [function () { initStage(L, R); }, function () { initTicks(L, R); }, initTabs, function () { initPath(R); }, initTable, function () { initClose(L, R); }]
      .forEach(function (f) { try { f(); } catch (err) { setTimeout(function () { throw err; }); } });
  }
  document.addEventListener('DOMContentLoaded', function () { setTimeout(init, 0); });
})();
